mapper.select:
select sl.class_path, sl.business_id, sl.module_type, sl.create_time as create_time, max(sl.create_user_name) as create_user_name, array_to_string(array_agg(DISTINCT sl.operation),',') as operation, array_to_string(array_agg(DISTINCT sl.content),',') as content from sys_log sl
sl.is_deleted = FALSE
AND sl.module_type = #{params.moduleType}
AND sl.business_id = #{params.businessId}
AND sl.pid = #{params.pid}
and ( sl.content ILIKE concat('%',#{params.searchKey}::text,'%') or sl.operation ILIKE concat('%',#{params.searchKey}::text,'%') or sl.create_user_name ILIKE concat('%',#{params.searchKey}::text,'%') )
group by sl.class_path,sl.business_id,sl.create_time,sl.module_type order by sl.create_time desc

select sl.class_path, sl.business_id, sl.create_time as create_time, max(sl.create_user_name) as create_user_name, array_to_string(array_agg(DISTINCT sl.operation),',') as operation, array_to_string(array_agg(DISTINCT sl.content),',') as content from sys_log sl
sl.is_deleted = FALSE
AND sl.module_type = #{params.moduleType}
AND sl.business_id = #{params.businessId}
AND sl.pid = #{params.pid}
group by sl.class_path,sl.business_id,sl.create_time,sl.module_type order by sl.create_time desc
